 73	export function parseSiteAnalyticsPayload(
 74	  value: unknown,
 75	): SiteAnalyticsEventPayload | undefined {
 76	  if (!isObjectRecord(value)) return undefined;
 77	
 78	  const event = parseSiteAnalyticsEvent(value.event);
 79	  if (!event) return undefined;
 80	
 81	  const dimension = value.dimension;
 82	  const allowedDimensions = SITE_ANALYTICS_DIMENSIONS[event];
 83	  if (!allowedDimensions) {
 84	    return dimension === undefined ? { event } : undefined;
 85	  }
 86	  if (typeof dimension !== "string" || !allowedDimensions.includes(dimension)) {
 87	    return undefined;
 88	  }
 89	  return { dimension, event };
 90	}
