 98	  try {
 99	    analytics.writeDataPoint({
100	      blobs: [payload.event, payload.dimension ?? "", referrerOrigin],
101	      doubles: [1],
102	      indexes: [payload.event],
103	    });
104	  } catch (error) {
105	    console.error(
106	      JSON.stringify({
107	        error: error instanceof Error ? error.message : "Unknown error",
108	        event: "site_analytics_write_failed",
109	        message: "site analytics write failed",
110	        siteEvent: payload.event,
111	      }),
112	    );
113	  }
114	}
