205	export function parseCampaignHeaders(headers: Headers): {
206	  campaign?: ShortlinkCampaign;
207	  error?: string;
208	} {
209	  const values = {
210	    medium: headers.get("x-shortlink-medium") ?? undefined,
211	    name: headers.get("x-shortlink-campaign") ?? undefined,
212	    source: headers.get("x-shortlink-source") ?? undefined,
213	  };
214	  if (Object.values(values).every((value) => value === undefined)) return {};
215	  return parseCampaign(values);
216	}
217	
218	export function validateInternalTarget(target: string): string | null {
219	  if (!target || target.length > MAX_INTERNAL_TARGET_LENGTH) {
220	    return "The internal target is empty or too long";
221	  }
222	  if (!target.startsWith("/") || target.startsWith("//")) {
223	    return "The internal target must be a same-origin path";
224	  }
225	  if (
226	    target.includes("\\") ||
227	    target.includes("#") ||
228	    hasControlCharacters(target)
229	  ) {
230	    return "The internal target is invalid";
231	  }
232	
233	  let parsed: URL;
234	  try {
235	    parsed = new URL(target, INTERNAL_TARGET_BASE_URL);
236	    const decodedPath = decodeURIComponent(parsed.pathname);
237	    const segments = decodedPath.split("/");
238	    if (segments.some((segment) => segment === "." || segment === "..")) {
239	      return "The internal target is invalid";
240	    }
241	  } catch {
242	    return "The internal target is invalid";
243	  }
244	
245	  if (
246	    parsed.pathname === "/api/shortlinks" ||
247	    parsed.pathname.startsWith("/api/shortlinks/") ||
248	    parsed.pathname === "/static/__shortlinks" ||
249	    parsed.pathname.startsWith("/static/__shortlinks/")
250	  ) {
251	    return "The internal target is reserved";
252	  }
253	
254	  const rootCode = parsed.pathname.slice(1);
255	  if (
256	    !parsed.pathname.slice(1).includes("/") &&
257	    isValidShortlinkCode(rootCode) &&
258	    !EXPLICIT_ROOT_PATHS.has(rootCode)
259	  ) {
260	    return "The internal target cannot point to another shortlink";
261	  }
262	
263	  return null;
264	}
265	
266	function generateCode(length: number, randomBytes: RandomBytes): string {
267	  const bytes = randomBytes(length);
268	  let code = "";
269	
270	  for (const byte of bytes) {
271	    code += SHORTLINK_ALPHABET[byte % SHORTLINK_ALPHABET.length];
272	  }
273	
274	  return code;
275	}
276	
277	async function allocateShortlink(
278	  target: ShortlinkTargetInput,
279	  storage: ShortlinkStorage,
280	  baseUrl: URL,
281	  randomBytes: RandomBytes,
282	  options: CreateShortlinkOptions,
283	): Promise<ShortlinkResult> {
284	  const normalizedOptions = normalizeCreateOptions(options);
285	  const record = buildRecord(target, normalizedOptions);
286	  const code = await findAvailableCode(record, storage, randomBytes);
287	  if (!code) {
288	    throw new ShortlinkCapacityError("Shortlink namespace is exhausted");
289	  }
290	
291	  return buildShortlinkResult(code, target, baseUrl, normalizedOptions);
292	}
293	
294	function buildRecord(
295	  target: ShortlinkTargetInput,
296	  options: CreateShortlinkOptions,
297	): ShortlinkRecord {
298	  if (target.path !== undefined) {
299	    const pathError = validateObjectKey(target.path);
300	    if (pathError) throw new InvalidShortlinkTargetError(pathError);
301	  } else if (target.target !== undefined) {
302	    const targetError = validateInternalTarget(target.target);
303	    if (targetError) throw new InvalidShortlinkTargetError(targetError);
304	  } else {
305	    throw new InvalidShortlinkTargetError("A shortlink target is required");
306	  }
307	
308	  let record: ShortlinkRecord;
309	  if (target.path !== undefined) {
310	    record = { path: target.path };
311	  } else if (target.target !== undefined) {
312	    record = { target: target.target };
313	  } else {
314	    throw new InvalidShortlinkTargetError("A shortlink target is required");
315	  }
316	  if (options.expiresAt) record.expiresAt = options.expiresAt.toISOString();
317	  if (options.campaign) record.campaign = options.campaign;
318	  return record;
319	}
320	
321	function buildShortlinkResult(
322	  code: string,
323	  target: ShortlinkTargetInput,
324	  baseUrl: URL,
325	  options: CreateShortlinkOptions,
326	): ShortlinkResult {
327	  const shortUrl = new URL(baseUrl);
328	  shortUrl.pathname = `/${code}`;
329	  shortUrl.search = "";
330	  shortUrl.hash = "";
331	
332	  const targetPath =
333	    target.path !== undefined ? `/static/${target.path}` : target.target!;
334	  const targetUrl = new URL(baseUrl);
335	  const parsedTarget = new URL(targetPath, baseUrl);
336	  targetUrl.pathname = parsedTarget.pathname;
337	  targetUrl.search = parsedTarget.search;
338	  targetUrl.hash = "";
339	
340	  const result: ShortlinkResult = {
341	    code,
342	    shortUrl: shortUrl.toString(),
343	    targetUrl: targetUrl.toString(),
344	  };
345	  if (target.path !== undefined) result.path = target.path;
346	  if (target.target !== undefined) result.target = target.target;
347	  if (options.expiresAt) result.expiresAt = options.expiresAt.toISOString();
348	  if (options.campaign) result.campaign = options.campaign;
349	  return result;
350	}
351	
352	async function findAvailableCode(
353	  record: ShortlinkRecord,
354	  storage: ShortlinkStorage,
355	  randomBytes: RandomBytes,
356	  length = SHORTLINK_MIN_LENGTH,
357	): Promise<string | null> {
358	  if (length > SHORTLINK_MAX_LENGTH) return null;
359	  const code = await findAvailableCodeAtLength(
360	    length,
361	    record,
362	    storage,
363	    randomBytes,
364	  );
365	  return code ?? findAvailableCode(record, storage, randomBytes, length + 1);
366	}
367	
368	async function findAvailableCodeAtLength(
369	  length: number,
370	  record: ShortlinkRecord,
371	  storage: ShortlinkStorage,
372	  randomBytes: RandomBytes,
373	  attempt = 0,
374	  attemptedCodes = new Set<string>(),
375	): Promise<string | null> {
376	  if (attempt >= SHORTLINK_ATTEMPTS_PER_LENGTH) return null;
377	  const code = generateCode(length, randomBytes);
378	  if (attemptedCodes.has(code)) {
379	    return findAvailableCodeAtLength(
380	      length,
381	      record,
382	      storage,
383	      randomBytes,
384	      attempt + 1,
385	      attemptedCodes,
386	    );
387	  }
388	  attemptedCodes.add(code);
389	  if (await storage.putIfAbsent(code, record)) return code;
390	  return findAvailableCodeAtLength(
391	    length,
392	    record,
393	    storage,
394	    randomBytes,
395	    attempt + 1,
396	    attemptedCodes,
397	  );
398	}
399	
400	async function createShortlinkFromRequest(
401	  request: Request,
402	  storage: ShortlinkStorage,
403	  uploadToken: string | undefined,
404	  targetStorage: ShortlinkTargetStorage | undefined,
405	  randomBytes: RandomBytes,
406	  siteAnalytics: SiteAnalytics | undefined,
407	): Promise<Response> {
408	  const authError = await authorizeMutation(
409	    request,
410	    uploadToken,
411	    "SHORTLINKS_NOT_CONFIGURED",
412	    "Shortlink writes are not configured",
413	  );
414	  if (authError) return authError;
415	
416	  const input = await parseShortlinkInput(request);
417	  if (input instanceof Response) return input;
418	
419	  let expiresAt = input.expiresAt;
420	  if (input.path !== undefined) {
421	    if (!targetStorage) {
422	      return apiError(
423	        503,
424	        "SHORTLINKS_NOT_CONFIGURED",
425	        "Shortlink writes are not configured",
426	      );
427	    }
428	
429	    const targetInfo = targetStorage.get
430	      ? await targetStorage.get(input.path)
431	      : (await targetStorage.exists(input.path))
432	        ? {}
433	        : null;
434	    if (!targetInfo) {
435	      return apiError(
436	        404,
437	        "STATIC_TARGET_NOT_FOUND",
438	        "The static file does not exist",
439	      );
440	    }

