123	export async function handleShortlinkRequest(
124	  request: Request,
125	  code: string | undefined,
126	  storage: ShortlinkStorage,
127	  uploadToken: string | undefined,
128	  targetStorage?: ShortlinkTargetStorage,
129	  randomBytes: RandomBytes = defaultRandomBytes,
130	  analytics?: ShortlinkAnalytics,
131	  siteAnalytics?: SiteAnalytics,
132	): Promise<Response> {
133	  try {
134	    if (request.method === "GET" || request.method === "HEAD") {
135	      if (!code) return methodNotAllowed();
136	      return resolveShortlink(request, code, storage, analytics);
137	    }
138	
139	    if (request.method === "POST") {
140	      if (code) return methodNotAllowed();
141	      return createShortlinkFromRequest(
142	        request,
143	        storage,
144	        uploadToken,
145	        targetStorage,
146	        randomBytes,
147	        siteAnalytics,
148	      );
149	    }
150	
151	    if (request.method === "DELETE") {
152	      if (!code) return methodNotAllowed();
153	      return deleteShortlink(
154	        request,
155	        code,
156	        storage,
157	        uploadToken,
158	        siteAnalytics,
159	      );
160	    }
161	
162	    return methodNotAllowed();
