176	export function parseCampaign(value: unknown): {
177	  campaign?: ShortlinkCampaign;
178	  error?: string;
179	} {
180	  if (value === undefined) return {};
181	  if (!isObjectRecord(value)) {
182	    return { error: invalidCampaignMessage() };
183	  }
184	
185	  const input = value;
186	  const campaign: ShortlinkCampaign = {};
187	  for (const field of ["name", "source", "medium"] as const) {
188	    const fieldValue = input[field];
189	    if (fieldValue === undefined) continue;
190	    if (
191	      typeof fieldValue !== "string" ||
192	      !CAMPAIGN_VALUE_PATTERN.test(fieldValue)
193	    ) {
194	      return { error: invalidCampaignMessage() };
195	    }
196	    campaign[field] = fieldValue;
197	  }
198	
199	  if (Object.keys(campaign).length === 0) {
200	    return { error: invalidCampaignMessage() };
201	  }
202	  return { campaign };
203	}
