218	export function validateInternalTarget(target: string): string | null {
219	  if (!target || target.length > MAX_INTERNAL_TARGET_LENGTH) {
220	    return "The internal target is empty or too long";
221	  }
222	  if (!target.startsWith("/") || target.startsWith("//")) {
223	    return "The internal target must be a same-origin path";
224	  }
225	  if (
226	    target.includes("\\") ||
227	    target.includes("#") ||
228	    hasControlCharacters(target)
229	  ) {
230	    return "The internal target is invalid";
231	  }
232	
233	  let parsed: URL;
234	  try {
235	    parsed = new URL(target, INTERNAL_TARGET_BASE_URL);
236	    const decodedPath = decodeURIComponent(parsed.pathname);
237	    const segments = decodedPath.split("/");
238	    if (segments.some((segment) => segment === "." || segment === "..")) {
239	      return "The internal target is invalid";
240	    }
241	  } catch {
242	    return "The internal target is invalid";
243	  }
244	
245	  if (
246	    parsed.pathname === "/api/shortlinks" ||
247	    parsed.pathname.startsWith("/api/shortlinks/") ||
248	    parsed.pathname === "/static/__shortlinks" ||
249	    parsed.pathname.startsWith("/static/__shortlinks/")
250	  ) {
251	    return "The internal target is reserved";
252	  }
253	
254	  const rootCode = parsed.pathname.slice(1);
255	  if (
256	    !parsed.pathname.slice(1).includes("/") &&
257	    isValidShortlinkCode(rootCode) &&
258	    !EXPLICIT_ROOT_PATHS.has(rootCode)
259	  ) {
260	    return "The internal target cannot point to another shortlink";
261	  }
262	
263	  return null;
264	}
