266	function generateCode(length: number, randomBytes: RandomBytes): string {
267	  const bytes = randomBytes(length);
268	  let code = "";
269	
270	  for (const byte of bytes) {
271	    code += SHORTLINK_ALPHABET[byte % SHORTLINK_ALPHABET.length];
272	  }
273	
274	  return code;
275	}
