352	async function findAvailableCode(
353	  record: ShortlinkRecord,
354	  storage: ShortlinkStorage,
355	  randomBytes: RandomBytes,
356	  length = SHORTLINK_MIN_LENGTH,
357	): Promise<string | null> {
358	  if (length > SHORTLINK_MAX_LENGTH) return null;
359	  const code = await findAvailableCodeAtLength(
360	    length,
361	    record,
362	    storage,
363	    randomBytes,
364	  );
365	  return code ?? findAvailableCode(record, storage, randomBytes, length + 1);
366	}
367	
368	async function findAvailableCodeAtLength(
369	  length: number,
370	  record: ShortlinkRecord,
371	  storage: ShortlinkStorage,
372	  randomBytes: RandomBytes,
373	  attempt = 0,
374	  attemptedCodes = new Set<string>(),
375	): Promise<string | null> {
376	  if (attempt >= SHORTLINK_ATTEMPTS_PER_LENGTH) return null;
377	  const code = generateCode(length, randomBytes);
378	  if (attemptedCodes.has(code)) {
379	    return findAvailableCodeAtLength(
380	      length,
381	      record,
382	      storage,
383	      randomBytes,
384	      attempt + 1,
385	      attemptedCodes,
386	    );
387	  }
388	  attemptedCodes.add(code);
389	  if (await storage.putIfAbsent(code, record)) return code;
390	  return findAvailableCodeAtLength(
391	    length,
392	    record,
393	    storage,
394	    randomBytes,
395	    attempt + 1,
396	    attemptedCodes,
397	  );
398	}
