400	async function createShortlinkFromRequest(
401	  request: Request,
402	  storage: ShortlinkStorage,
403	  uploadToken: string | undefined,
404	  targetStorage: ShortlinkTargetStorage | undefined,
405	  randomBytes: RandomBytes,
406	  siteAnalytics: SiteAnalytics | undefined,
407	): Promise<Response> {
408	  const authError = await authorizeMutation(
409	    request,
410	    uploadToken,
411	    "SHORTLINKS_NOT_CONFIGURED",
412	    "Shortlink writes are not configured",
413	  );
414	  if (authError) return authError;
415	
416	  const input = await parseShortlinkInput(request);
417	  if (input instanceof Response) return input;
418	
419	  let expiresAt = input.expiresAt;
420	  if (input.path !== undefined) {
421	    if (!targetStorage) {
422	      return apiError(
423	        503,
424	        "SHORTLINKS_NOT_CONFIGURED",
425	        "Shortlink writes are not configured",
426	      );
427	    }
428	
429	    const targetInfo = targetStorage.get
430	      ? await targetStorage.get(input.path)
431	      : (await targetStorage.exists(input.path))
432	        ? {}
433	        : null;
434	    if (!targetInfo) {
435	      return apiError(
436	        404,
437	        "STATIC_TARGET_NOT_FOUND",
438	        "The static file does not exist",
439	      );
440	    }

