277	async function allocateShortlink(
278	  target: ShortlinkTargetInput,
279	  storage: ShortlinkStorage,
280	  baseUrl: URL,
281	  randomBytes: RandomBytes,
282	  options: CreateShortlinkOptions,
283	): Promise<ShortlinkResult> {
284	  const normalizedOptions = normalizeCreateOptions(options);
285	  const record = buildRecord(target, normalizedOptions);
286	  const code = await findAvailableCode(record, storage, randomBytes);
287	  if (!code) {
288	    throw new ShortlinkCapacityError("Shortlink namespace is exhausted");
289	  }
290	
291	  return buildShortlinkResult(code, target, baseUrl, normalizedOptions);
292	}
