294	function buildRecord(
295	  target: ShortlinkTargetInput,
296	  options: CreateShortlinkOptions,
297	): ShortlinkRecord {
298	  if (target.path !== undefined) {
299	    const pathError = validateObjectKey(target.path);
300	    if (pathError) throw new InvalidShortlinkTargetError(pathError);
301	  } else if (target.target !== undefined) {
302	    const targetError = validateInternalTarget(target.target);
303	    if (targetError) throw new InvalidShortlinkTargetError(targetError);
304	  } else {
305	    throw new InvalidShortlinkTargetError("A shortlink target is required");
306	  }
307	
308	  let record: ShortlinkRecord;
309	  if (target.path !== undefined) {
310	    record = { path: target.path };
311	  } else if (target.target !== undefined) {
312	    record = { target: target.target };
313	  } else {
314	    throw new InvalidShortlinkTargetError("A shortlink target is required");
315	  }
316	  if (options.expiresAt) record.expiresAt = options.expiresAt.toISOString();
317	  if (options.campaign) record.campaign = options.campaign;
318	  return record;
319	}
