321	function buildShortlinkResult(
322	  code: string,
323	  target: ShortlinkTargetInput,
324	  baseUrl: URL,
325	  options: CreateShortlinkOptions,
326	): ShortlinkResult {
327	  const shortUrl = new URL(baseUrl);
328	  shortUrl.pathname = `/${code}`;
329	  shortUrl.search = "";
330	  shortUrl.hash = "";
331	
332	  const targetPath =
333	    target.path !== undefined ? `/static/${target.path}` : target.target!;
334	  const targetUrl = new URL(baseUrl);
335	  const parsedTarget = new URL(targetPath, baseUrl);
336	  targetUrl.pathname = parsedTarget.pathname;
337	  targetUrl.search = parsedTarget.search;
338	  targetUrl.hash = "";
339	
340	  const result: ShortlinkResult = {
341	    code,
342	    shortUrl: shortUrl.toString(),
343	    targetUrl: targetUrl.toString(),
344	  };
345	  if (target.path !== undefined) result.path = target.path;
346	  if (target.target !== undefined) result.target = target.target;
347	  if (options.expiresAt) result.expiresAt = options.expiresAt.toISOString();
348	  if (options.campaign) result.campaign = options.campaign;
349	  return result;
350	}
