   511	async function parseShortlinkInput(
   512	  request: Request,
   513	): Promise<ParsedShortlinkInput | Response> {
   514	  const contentType = request.headers.get("content-type")?.toLowerCase() ?? "";
   515	  if (!contentType.startsWith("application/json")) {
   516	    return apiError(
   517	      415,
   518	      "UNSUPPORTED_MEDIA_TYPE",
   519	      "Shortlink creation requires application/json",
   520	    );
   521	  }
   522	
   523	  const contentLength = request.headers.get("content-length");
   524	  if (contentLength === null) {
   525	    return apiError(
   526	      411,
   527	      "LENGTH_REQUIRED",
   528	      "Content-Length is required for shortlink creation",
   529	    );
   530	  }
   531	  if (!/^\d+$/.test(contentLength)) {
   532	    return apiError(400, "INVALID_CONTENT_LENGTH", "Content-Length is invalid");
   533	  }
   534	
   535	  const parsedLength = Number(contentLength);
   536	  if (!Number.isSafeInteger(parsedLength)) {
   537	    return apiError(400, "INVALID_CONTENT_LENGTH", "Content-Length is invalid");
   538	  }
   539	  if (parsedLength > MAX_SHORTLINK_REQUEST_BYTES) {
   540	    return apiError(
   541	      413,
   542	      "REQUEST_TOO_LARGE",
   543	      "Shortlink creation requests are limited to 8 KiB",
   544	    );
   545	  }
   546	
   547	  let input: unknown;
   548	  try {
   549	    input = await request.json();
   550	  } catch {
   551	    return apiError(400, "INVALID_JSON", "The request body must be valid JSON");
   552	  }
   553	  if (!isObjectRecord(input)) {
   554	    return apiError(
   555	      400,
   556	      "INVALID_TARGET",
   557	      "The request body must contain either a string path or target",
   558	    );
   559	  }
   560	
   561	  const body = input;
   562	  const hasPath = "path" in body;
   563	  const hasTarget = "target" in body;
   564	  if (hasPath === hasTarget) {
   565	    return apiError(
   566	      400,
   567	      "INVALID_TARGET",
   568	      "The request body must contain exactly one of path or target",
   569	    );
   570	  }
   571	
   572	  const result: ParsedShortlinkInput = {};
   573	  if (hasPath) {
   574	    if (typeof body.path !== "string") {
   575	      return apiError(400, "INVALID_TARGET_PATH", "Path must be a string");
   576	    }
   577	    const pathError = validateObjectKey(body.path);
   578	    if (pathError) return apiError(400, "INVALID_TARGET_PATH", pathError);
   579	    result.path = body.path;
   580	  } else {
   581	    if (typeof body.target !== "string") {
   582	      return apiError(
   583	        400,
   584	        "INVALID_INTERNAL_TARGET",
   585	        "Target must be a string",
   586	      );
   587	    }
   588	    const targetError = validateInternalTarget(body.target);
   589	    if (targetError)
   590	      return apiError(400, "INVALID_INTERNAL_TARGET", targetError);
   591	    result.target = body.target;
   592	  }
   593	
   594	  const expiration = parseExpiration(body.expiresAt);
   595	  if (expiration.error) {
   596	    return apiError(400, "INVALID_EXPIRATION", expiration.error);
   597	  }
