   599	
   600	  const campaign = parseCampaign(body.campaign);
   601	  if (campaign.error) return apiError(400, "INVALID_CAMPAIGN", campaign.error);
   602	  if (campaign.campaign) result.campaign = campaign.campaign;
   603	  return result;
   604	}
