   606	async function resolveShortlink(
   607	  request: Request,
   608	  code: string,
   609	  storage: ShortlinkStorage,
   610	  analytics?: ShortlinkAnalytics,
   611	): Promise<Response> {
   612	  if (!isValidShortlinkCode(code)) return shortlinkNotFound();
   613	
   614	  const record = await storage.get(code);
   615	  if (!record) return shortlinkNotFound();
   616	
   617	  const targetPath = record.path;
   618	  const target = record.target;
   619	  if (targetPath !== undefined && target !== undefined) {
   620	    return apiError(500, "INVALID_RECORD", "Shortlink record is invalid");
   621	  }
   622	
   623	  let targetUrl: URL;
   624	  if (targetPath !== undefined) {
   625	    const pathError = validateObjectKey(targetPath);
   626	    if (pathError) {
   627	      console.error(
   628	        JSON.stringify({
   629	          code,
   630	          message: "shortlink record has an invalid target path",
   631	        }),
   632	      );
   633	      return apiError(500, "INVALID_RECORD", "Shortlink record is invalid");
   634	    }
   635	    targetUrl = new URL(request.url);
   636	    targetUrl.pathname = `/static/${targetPath}`;
   637	    targetUrl.search = "";
   638	    targetUrl.hash = "";
   639	  } else if (target !== undefined) {
   640	    const targetError = validateInternalTarget(target);
   641	    if (targetError) {
   642	      console.error(
   643	        JSON.stringify({
   644	          code,
   645	          message: "shortlink record has an invalid internal target",
   646	        }),
   647	      );
   648	      return apiError(500, "INVALID_RECORD", "Shortlink record is invalid");
   649	    }
   650	    targetUrl = new URL(target, request.url);
   651	    targetUrl.hash = "";
   652	  } else {
   653	    return apiError(500, "INVALID_RECORD", "Shortlink record is invalid");
   654	  }
   655	
   656	  const expiresAt = record.expiresAt
   657	    ? parseStoredExpiration(record.expiresAt)
   658	    : undefined;
   659	  if (record.expiresAt && !expiresAt) {
   660	    return apiError(500, "INVALID_RECORD", "Shortlink record is invalid");
   661	  }
   662	  if (expiresAt && expiresAt.getTime() <= Date.now()) {
   663	    return expiredShortlinkResponse(request, expiresAt);
   664	  }
   665	
   666	  if (request.method === "GET" && analytics) {
   667	    trackShortlinkClick(request, code, record.campaign, analytics);
   668	  }
   669	
   670	  return new Response(null, {
   671	    status: 302,
   672	    headers: {
   673	      "Cache-Control":
   674	        expiresAt || record.campaign ? "no-store" : "public, max-age=300",
   675	      Location: targetUrl.toString(),
   676	    },
   677	  });
   678	}
