 12	
 13	function toStaticFileObject(object: R2Object | R2ObjectBody): StaticFileObject {
 14	  const metadata = object.httpMetadata;
 15	  const expiresAtValue = object.customMetadata?.expiresAt;
 16	  const expiresAt = expiresAtValue ? new Date(expiresAtValue) : undefined;
 17	  if (expiresAt && !Number.isFinite(expiresAt.getTime())) {
 18	    throw new Error("Static file has invalid expiration metadata");
 19	  }
 20	  const result: StaticFileObject = {
 21	    body: "body" in object ? object.body : null,
 22	    httpEtag: object.httpEtag,
 23	    metadata: {
 24	      cacheControl: metadata?.cacheControl ?? "public, max-age=300",
 25	      contentType: metadata?.contentType ?? "application/octet-stream",
 26	    },
 27	    size: object.size,
 28	    uploaded: object.uploaded,
 29	  };
 30	  if (expiresAt) result.expiresAt = expiresAt;
 31	  if (metadata?.contentDisposition) {
 32	    result.metadata.contentDisposition = metadata.contentDisposition;
 33	  }
 34	  if (metadata?.contentEncoding)
 35	    result.metadata.contentEncoding = metadata.contentEncoding;
 36	  if (metadata?.contentLanguage)
 37	    result.metadata.contentLanguage = metadata.contentLanguage;
 38	  return result;
 39	}
 40	
 41	function createStorage(bucket: R2Bucket): StaticFileStorage {
 42	  return {
 43	    async delete(key) {
 44	      await bucket.delete(key);
 45	    },
 46	    async get(key) {
 47	      const object = await bucket.get(key);
 48	      return object ? toStaticFileObject(object) : null;
 49	    },
 50	    async head(key) {
 51	      const object = await bucket.head(key);
 52	      return object ? toStaticFileObject(object) : null;
 53	    },
 54	    async put(key, value, metadata: StaticFileMetadata, expiresAt?: Date) {
 55	      const object = await bucket.put(key, value, {
 56	        httpMetadata: metadata,
 57	        ...(expiresAt
 58	          ? { customMetadata: { expiresAt: expiresAt.toISOString() } }
 59	          : {}),
 60	      });
 61	      return toStaticFileObject(object);
 62	    },
 63	  };
 64	}
 65	
 66	function uploadToken(): string | undefined {
 67	  const value: unknown = Reflect.get(env, "STATIC_UPLOAD_TOKEN");
 68	  return typeof value === "string" && value.length > 0 ? value : undefined;
 69	}
