 13	  if (request.method !== "POST") {
 14	    return apiError(
 15	      405,
 16	      "METHOD_NOT_ALLOWED",
 17	      "Site analytics events require POST",
 18	      { Allow: "POST" },
 19	    );
 20	  }
 21	
 22	  const contentType = request.headers.get("content-type")?.toLowerCase() ?? "";
 23	  if (!contentType.startsWith("application/json")) {
 24	    return apiError(
 25	      415,
 26	      "UNSUPPORTED_MEDIA_TYPE",
 27	      "Site analytics events require application/json",
 28	    );
 29	  }
 30	
 31	  const contentLength = Number(request.headers.get("content-length"));
 32	  if (
 33	    Number.isFinite(contentLength) &&
