 45	    body = await request.text();
 46	  } catch {
 47	    return apiError(400, "INVALID_EVENT", "Site analytics event is invalid");
 48	  }
 49	  if (
 50	    new TextEncoder().encode(body).byteLength > MAX_SITE_ANALYTICS_REQUEST_BYTES
 51	  ) {
 52	    return apiError(
 53	      413,
 54	      "REQUEST_TOO_LARGE",
 55	      "Site analytics event is too large",
 56	    );
 57	  }
