 55	export async function handleStaticFileRequest(
 56	  request: Request,
 57	  key: string | undefined,
 58	  storage: StaticFileStorage,
 59	  uploadToken: string | undefined,
 60	  shortlinkStorage?: ShortlinkStorage,
 61	  randomBytes?: RandomBytes,
 62	  siteAnalytics?: SiteAnalytics,
 63	): Promise<Response> {
 64	  if (!key) return apiError(400, "INVALID_PATH", "A file path is required");
 65	  const pathError = validateObjectKey(key);
 66	  if (pathError) return apiError(400, "INVALID_PATH", pathError);
 67	
 68	  try {
 69	    switch (request.method) {
 70	      case "GET":
 71	        return serveObject(await storage.get(key), false);
 72	      case "HEAD":
 73	        return serveObject(await storage.head(key), true);
 74	      case "POST":
 75	        return uploadObject(
 76	          request,
 77	          key,
 78	          storage,
 79	          uploadToken,
 80	          shortlinkStorage,
 81	          randomBytes,
 82	          siteAnalytics,
 83	        );
 84	      case "DELETE":
 85	        return deleteObject(request, key, storage, uploadToken, siteAnalytics);
 86	      default:
 87	        return apiError(405, "METHOD_NOT_ALLOWED", "Method not allowed", {
 88	          Allow: ALLOWED_METHODS,
 89	        });
 90	    }
 91	  } catch (error) {
 92	    if (error instanceof UploadTooLargeError) {
 93	      return apiError(
 94	        413,
 95	        "FILE_TOO_LARGE",
 96	        "Static files are limited to 100 MiB",
 97	      );
 98	    }
 99	
100	    console.error(
101	      JSON.stringify({
102	        error: error instanceof Error ? error.message : "Unknown error",
103	        message: "static file request failed",
104	        method: request.method,
105	        path: key,
106	      }),
107	    );
108	    return apiError(500, "INTERNAL_ERROR", "Static file request failed");
109	  }
110	}
