274	
275	  if (object.expiresAt && object.expiresAt.getTime() <= Date.now()) {
276	    const headers = expirationHeaders(object.expiresAt);
277	    const response = apiError(
278	      410,
279	      "EXPIRED",
280	      "Static file has expired",
281	      headers,
282	    );
283	    return headOnly
284	      ? new Response(null, {
285	          status: response.status,
286	          headers: response.headers,
287	        })
288	      : response;
289	  }
