291	  const headers = new Headers({
292	    "Cache-Control": object.expiresAt
293	      ? "no-store"
294	      : object.metadata.cacheControl,
295	    "Content-Length": String(object.size),
296	    "Content-Type": object.metadata.contentType,
297	    ETag: object.httpEtag,
298	    "Last-Modified": object.uploaded.toUTCString(),
299	    "X-Content-Type-Options": "nosniff",
300	  });
301	  setOptionalHeader(
302	    headers,
303	    "Content-Disposition",
304	    object.metadata.contentDisposition,
305	  );
306	  setOptionalHeader(
307	    headers,
308	    "Content-Encoding",
309	    object.metadata.contentEncoding,
310	  );
311	  setOptionalHeader(
312	    headers,
313	    "Content-Language",
314	    object.metadata.contentLanguage,
315	  );
316	  if (object.expiresAt) {
317	    const expiresAtHeaders = expirationHeaders(object.expiresAt);
318	    for (const [name, value] of expiresAtHeaders) headers.set(name, value);
319	  }
320	
321	  return new Response(headOnly ? null : object.body, { headers });
322	}
