366	    contentType: headers.get("content-type") ?? "application/octet-stream",
367	  };
368	  copyHeader(headers, "content-disposition", metadata, "contentDisposition");
369	  copyHeader(headers, "content-encoding", metadata, "contentEncoding");
370	  copyHeader(headers, "content-language", metadata, "contentLanguage");
