payload.input:
const queries = [
  "SELECT toDate(timestamp) AS day, sum(_sample_interval) AS clicks FROM leenk_shortlinks GROUP BY day ORDER BY day",
  "SELECT blob1 AS code, blob2 AS campaign, blob3 AS source, blob4 AS medium, sum(_sample_interval) AS clicks FROM leenk_shortlinks GROUP BY code, campaign, source, medium ORDER BY clicks DESC LIMIT 20",
  "SELECT blob5 AS referrer_origin, sum(_sample_interval) AS clicks FROM leenk_shortlinks WHERE blob5 != '' GROUP BY referrer_origin ORDER BY clicks DESC LIMIT 20"
];
const results = await Promise.all(queries.map((query) => tools.exec_command({
  cmd:`token=$(awk -F' = ' '$1 == "oauth_token" {gsub(/"/, "", $2); print $2; exit}' "$HOME/Library/Preferences/.wrangler/config/default.toml"); curl -sS 'https://api.cloudflare.com/client/v4/accounts/662932437092ddb243ba32ae7e986e75/analytics_engine/sql' -H "Authorization: Bearer $token" --data ${JSON.stringify(query)}; curl_exit=$?; unset token; exit $curl_exit`,
  workdir:"/Users/yusoofsh/Developer/Playground/leenk",
  yield_time_ms:30000,
  max_output_tokens:12000
})));
results.forEach((r,i)=>{ text(`QUERY_${i+1}\n${r.output}`); });

