export function deriveShortlinkLabel(target: ShortlinkTargetInput): string {
  const raw = (target.path ?? target.target ?? DEFAULT_SHORTLINK_LABEL)
    .replace(/[?#].*$/, "")
    .replace(/^\/+/, "")
    .replace(/[^A-Za-z0-9._/-]+/g, "_")
