{"cmd": "TOKEN=REDACTED
FAILED=0
for f in ~/.agent/diagrams/*; do
  name=$(basename "$f")
  case "$name" in
    *.html) CT=text/html ;;
    *.png) CT=image/png ;;
    *) CT=application/octet-stream ;;
  esac
  code=$(curl -s -o /dev/null -w "%{http_code}" --max-time 60 -X POST "https://www.yusoofsh.id/static/$name" -H "Authorization: Bearer $TOKEN" -H "Content-Type: $CT" -H "X-Static-Expires-In: never" --data-binary "@$f")
  if [ "$code" != "200" ]; then echo "FAIL $code $name"; FAILED=$((FAILED+1)); fi
done
echo "done, failed=$FAILED"", "yield_time_ms": 180000}

