  for (let index = 0; index < count; index += 1) {
    const x = Math.floor(random() * STAR_FIELD_SIZE) - STAR_FIELD_OFFSET;
    const y = Math.floor(random() * STAR_FIELD_SIZE) - STAR_FIELD_OFFSET;
    shadows.push(`${x}px ${y}px`);
  }

  return shadows.join(", ");
};

