```ts
export const MAX_INLINE_LINKS = 16;
export const INLINE_LINK_PATTERN = /\[([^\[\]]{1,128})\]\((url|email|internal|shortlink):([^()\s]{1,2048})\)/g;

export function validateInlineLinks(text: string): string | null {
  let count = 0;
  for (const match of text.matchAll(INLINE_LINK_PATTERN)) {
    count += 1;
    if (count > MAX_INLINE_LINKS) return `Text is limited to ${MAX_INLINE_LINKS} inline links`;
    const [, label, kind, target] = match;
    const targetError = validateLinkTarget(kind as CmsLinkKind, target);
    if (targetError) return targetError;
    if (label.includes("[") || label.includes("]")) return "Link labels are invalid";
  }
  return null;
}

