    text: `Bismillah. I'm a Malang-based full-stack and platform engineer focused on TypeScript applications, data workflows, CI/CD, Kubernetes, and production reliability. Recently, I improved [NADI](url:https://nadi.co.id/)'s payment workflow through a DOKU migration, modernized [YDSF](url:https://ydsf.org/)'s donation platform, and migrated seven [ElectGo](url:https://electgo.com/) production deployments plus 300+ n8n workflows to Amazon EKS. Open to meaningful remote or contract collaborations. Reach me via ${HOME_LINK} / ${TWITTER_LINK} / ${LINKEDIN_LINK} / ${GITHUB_LINK}. Baarakallahu fiik.`,
    type: "paragraph",
  },
];

export const HOMEPAGE_SEO = {
  seoDescription:
    "Malang-based full-stack/DevOps engineer. Accelerated time-to-production at Nadi; built YDSF's Muslim crowdfunding platform end-to-end. TypeScript/React, Hono/Bun, Docker/Traefik/Tailscale, OpenTelemetry/Sentry, UU PDP-aware.",
  seoKeywords:
    "Yusoof Moh, full-stack engineer Indonesia, DevOps Indonesia, TypeScript React, Hono Bun, Docker Traefik Tailscale, OpenTelemetry Sentry, UU PDP compliance, Nadi, YDSF, crowdfunding platform",
  seoTitle: "Yusoof Moh \u2014 Full-Stack/DevOps Engineer in Indonesia",
  title: "Meet me, Yusoof Moh",
} as const;

export const HOMEPAGE_PROFILE_METADATA = {
  email: "me@yusoofsh.id",
  location: "Malang, Indonesia",
  name: "Yusoof Moh",
} as const;

export function buildHomepageRevisionContent(): CmsRevisionContent {
  return {
    blocksFull: FULL_BLOCKS,
    blocksTldr: TLDR_BLOCKS,
    profileMetadata: { ...HOMEPAGE_PROFILE_METADATA },
    seoDescription: HOMEPAGE_SEO.seoDescription,
    seoKeywords: HOMEPAGE_SEO.seoKeywords,
    seoTitle: HOMEPAGE_SEO.seoTitle,
    socialCopy: HOMEPAGE_SEO.seoDescription,
    title: HOMEPAGE_SEO.title,
  };
}

import {
  blockInsertStatements,
  contentDigest,
  generateCmsId,
  nextRevisionNumber,
  type CmsRevisionContent,
  type SqlStatement,
} from "./cms";
import {
  bootstrapCmsDatabase,
  getContentDocument,
  getLatestRevisionNumber,
  toD1Like,
  toPreparedStatements,
  type D1Like,
} from "./cms-db";
import { buildHomepageRevisionContent } from "~/lib/homepage-content";

export function importHomepageStatements(args: {
  actor: string;
  content: CmsRevisionContent;
  createdAt: string;
  documentId: string;
  payloadHash: string;
  revisionId: string;
  revisionNumber: number;
}): SqlStatement[] {
  return [
    {
      sql: `INSERT INTO content_revisions (
  id, document_id, number, state, title, seo_title, seo_description,
  seo_keywords, social_copy, profile_metadata, payload_hash, author,
  created_at
) VALUES (?, ?, ?, 'published', ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      params: [
        args.revisionId,
        args.documentId,
        args.revisionNumber,
        args.content.title,
        args.content.seoTitle,
        args.content.seoDescription,
        args.content.seoKeywords,
        args.content.socialCopy,
        JSON.stringify(args.content.profileMetadata),
        args.payloadHash,
        args.actor,
        args.createdAt,
      ],
    },
    ...blockInsertStatements(args.revisionId, "full", args.content.blocksFull),
    ...blockInsertStatements(args.revisionId, "tldr", args.content.blocksTldr),
    {
      sql: `UPDATE content_documents
SET published_revision_id = ?, updated_at = ?
WHERE key = ?`,
      params: [args.revisionId, args.createdAt, "homepage"],
    },
    {
      sql: `INSERT INTO activity_entries (id, kind, actor, summary, payload, created_at)
VALUES (?, 'imported', ?, ?, ?, ?)`,
      params: [
        generateCmsId(),
        args.actor,
        `Imported the homepage as revision ${args.revisionNumber}`,
        JSON.stringify({ revisionId: args.revisionId }),
        args.createdAt,
      ],
    },
  ];
}

/**
 * Seeds the homepage document with its first Published Revision when none
 * exists. Idempotent: once a revision is published, operator content wins
 * and source changes never overwrite it.
 */
export async function ensureHomepageImported(db: D1Like): Promise<boolean> {
  await bootstrapCmsDatabase(db);
  const document = await getContentDocument(db);
  if (document && document.published_revision_id !== null) return false;

  const content = buildHomepageRevisionContent();
  const payloadHash = await contentDigest(content);
  const latest = await getLatestRevisionNumber(db);
  const createdAt = new Date().toISOString();
  const statements = importHomepageStatements({
    actor: "system",
    content,
    createdAt,
    documentId: document?.id ?? "homepage",
    payloadHash,
    revisionId: generateCmsId(),
    revisionNumber: nextRevisionNumber(latest),
  });
  await db.batch(toPreparedStatements(db, statements));
  return true;
}

export { toD1Like };

import {
  INLINE_LINK_PATTERN,
  validateCmsText,
  type CmsBlock,
  type CmsLinkKind,
} from "./dashboard/cms";

const SECTION_ANALYTICS_KEYS: Record<string, string> = {
  "Beyond work": "beyond_work",
  "Selected work": "selected_work",
  "What I do": "what_i_do",
};

const KNOWN_EXTERNAL_DIMENSIONS: Record<string, string> = {
  "electgo.com": "electgo",
  "nadi.co.id": "nadi",
  "ydsf.org": "ydsf",
};

const KNOWN_INTERNAL_DIMENSIONS: Record<string, string> = {
  "/github": "github",
  "/linkedin": "linkedin",
  "/twitter": "twitter",
};

function escapeHtml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function linkAnalytics(
  kind: CmsLinkKind,
  target: string,
): { dimension?: string; event?: string } {
  if (kind === "email") {
    return { dimension: "email", event: "contact_link_clicked" };
  }
  if (kind === "internal") {
    const dimension = KNOWN_INTERNAL_DIMENSIONS[target];
    return dimension
      ? { dimension, event: "social_link_clicked" }
      : {};
  }
  if (kind === "url") {
    try {
      const host = new URL(target).hostname.replace(/^www\./, "");
      const dimension = KNOWN_EXTERNAL_DIMENSIONS[host];
      return dimension ? { dimension, event: "outbound_link_clicked" } : {};
    } catch {
      return {};
    }
  }
  return {};
}

function linkHref(kind: CmsLinkKind, target: string): string {
  if (kind === "email") return `mailto:${target}`;
  return target;
}

function renderInlineLink(
  label: string,
  kind: CmsLinkKind,
  target: string,
): string {
  const analytics = linkAnalytics(kind, target);
  const attributes = [
    `href="${escapeHtml(linkHref(kind, target))}"`,
    analytics.event
      ? `data-analytics-event="${analytics.event}"`
      : "",
    analytics.dimension
      ? `data-analytics-dimension="${analytics.dimension}"`
      : "",
  ]
    .filter(Boolean)
    .join(" ");
  return `<a ${attributes}>${escapeHtml(label)}</a>`;
}

export function renderInlineText(text: string): string {
  let result = "";
  let lastIndex = 0;
  for (const match of text.matchAll(INLINE_LINK_PATTERN)) {
    const index = match.index ?? 0;
    result += escapeHtml(text.slice(lastIndex, index));
    const [, label, kind, target] = match;
    result += renderInlineLink(
      label ?? "",
      (kind ?? "url") as CmsLinkKind,
      target ?? "",
    );
    lastIndex = index + match[0].length;
  }
  result += escapeHtml(text.slice(lastIndex));
  return result;
}

export function renderBlock(block: CmsBlock): string {
  switch (block.type) {
    case "intro":
      return `<p>${renderInlineText(block.text)}</p>`;
    case "paragraph":
      return `<p>${renderInlineText(block.text)}</p>`;
    case "section": {
      const analyticsKey = SECTION_ANALYTICS_KEYS[block.heading];
      const attributes = analyticsKey
        ? ` data-analytics-section="${analyticsKey}"`
        : "";
      const text = block.text ? `<p>${renderInlineText(block.text)}</p>` : "";
      return `<h2${attributes}>${escapeHtml(block.heading)}</h2>${text}`;
    }
    case "bullet_list": {
      const items = block.items
        .map((item) => `<li>${renderInlineText(item)}</li>`)
        .join("");
      return `<ul>${items}</ul>`;
    }
    case "contact": {
      const email = `<a href="mailto:${escapeHtml(block.email)}" data-analytics-event="contact_link_clicked" data-analytics-dimension="email">${escapeHtml(block.email)}</a>`;
      const links = block.links
        .map((link) =>
          renderInlineLink(link.label, link.kind, link.target),
        )
        .join(" / ");
      return `<p>${email}${links ? ` / ${links}` : ""}</p>`;
    }
  }
}

export function renderHomepageBlocks(blocks: CmsBlock[]): string {
  return blocks.map(renderBlock).join("\n");
}

export { validateCmsText };

