```ts
import { env } from "cloudflare:workers";
import { defineMiddleware } from "astro/middleware";

const DASHBOARD_PREFIXES = ["/dashboard", "/api/dashboard"];

async function constantTimeEqual(a: string, b: string): Promise<boolean> {
  const bytes = await Promise.all([
    crypto.subtle.digest("SHA-256", new TextEncoder().encode(a)),
    crypto.subtle.digest("SHA-256", new TextEncoder().encode(b)),
  ]);
  if (bytes[0].byteLength !== bytes[1].byteLength) return false;
  const x = new Uint8Array(bytes[0]);
  const y = new Uint8Array(bytes[1]);
  let diff = 0;
  for (let i = 0; i < x.length; i += 1) diff |= x[i] ^ y[i];
  return diff === 0;
}

export const onRequest = defineMiddleware(async (context, next) => {
  const url = new URL(context.request.url);
  const protectedPath = DASHBOARD_PREFIXES.some((prefix) => url.pathname === prefix || url.pathname.startsWith(`${prefix}/`));
  if (!protectedPath) return next();

  const expected = env.STATIC_UPLOAD_TOKEN;
  if (!expected) {
    return new Response("Dashboard authentication is not configured", { status: 503 });
  }
  const header = context.request.headers.get("authorization") ?? "";
  const [scheme, credentials] = header.split(" ");
  let ok = false;
  if (scheme?.toLowerCase() === "basic" && credentials) {
    try {
      const decoded = atob(credentials);
      const password = decoded.split(":")[1] ?? "";
      ok = await constantTimeEqual(password, expected);
    } catch { ok = false; }
  }
  if (!ok) {
    return new Response("Authentication required", {
      status: 401,
      headers: { "WWW-Authenticate": 'Basic realm="Leenk dashboard", charset="UTF-8"', "Cache-Control": "no-store" },
    });
  }
  return next();
});
```

